22	import java.time.DayOfWeek;
23	import java.time.LocalDate;
24	import java.util.Collection;
25	import java.util.Comparator;
26	import java.util.List;
27	import java.util.Map;
28	
29	import org.slf4j.Logger;
30	import org.slf4j.LoggerFactory;
31	import org.springframework.http.HttpHeaders;
32	import org.springframework.http.HttpStatus;
33	import org.springframework.http.ResponseEntity;
34	import org.springframework.samples.petclinic.mapper.OwnerMapper;
35	import org.springframework.samples.petclinic.mapper.PetMapper;
36	import org.springframework.samples.petclinic.mapper.VisitMapper;
37	import org.springframework.samples.petclinic.model.Owner;
38	import org.springframework.samples.petclinic.model.Pet;
39	import org.springframework.samples.petclinic.model.Visit;
40	import org.springframework.samples.petclinic.rest.api.OwnersApi;
41	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
42	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.PetDto;
44	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
45	import org.springframework.samples.petclinic.rest.dto.VisitDto;
46	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
47	import org.springframework.samples.petclinic.service.ClinicService;
48	import org.springframework.security.access.prepost.PreAuthorize;
49	import org.springframework.web.bind.annotation.CrossOrigin;
50	import org.springframework.web.bind.annotation.RequestMapping;
51	import org.springframework.web.bind.annotation.RestController;
52	import org.springframework.web.util.UriComponentsBuilder;
53	
54	import jakarta.transaction.Transactional;
55	
56	/**
57	 * @author Vitaliy Fedoriv
58	 */
59	
60	@RestController
61	@CrossOrigin(exposedHeaders = "errors, content-type")
62	@RequestMapping("/api")
63	public class OwnerRestControllerV1 implements OwnersApi {
64	
65	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
66	
67	    private final ClinicService clinicService;
68	
69	    private final OwnerMapper ownerMapper;
70	
71	    private final PetMapper petMapper;
72	
73	    private final VisitMapper visitMapper;
74	
75	    private final AddressNormalizer addressNormalizer;
76	
77	    public OwnerRestControllerV1(ClinicService clinicService,
78	                                 OwnerMapper ownerMapper,
79	                                 PetMapper petMapper,
80	                                 VisitMapper visitMapper,
81	                                 AddressNormalizer addressNormalizer) {
82	        this.clinicService = clinicService;
83	        this.ownerMapper = ownerMapper;
84	        this.petMapper = petMapper;
85	        this.visitMapper = visitMapper;
86	        this.addressNormalizer = addressNormalizer;
87	    }
88	
89	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
90	    @Override
91	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
92	        Collection<Owner> owners;
93	        if (lastName != null) {
94	            owners = this.clinicService.findOwnerByLastName(lastName);
95	        } else {
96	            owners = this.clinicService.findAllOwners();
97	        }
98	        if (owners.isEmpty()) {
99	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
100	        }
101	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
102	    }
103	
104	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
105	    @Override
106	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
107	        Owner owner = this.clinicService.findOwnerById(ownerId);
108	        if (owner == null) {
109	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
110	        }
111	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
112	    }
113	
114	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
115	    @Override
116	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
117	        HttpHeaders headers = new HttpHeaders();
118	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
119	        String address = addressNormalizer.normalize(owner.getAddress());
120	        if (address.isEmpty()) {
121	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
122	        }
123	        owner.setAddress(address);
124	        String telephone = toE164(owner.getTelephone());
125	        if (telephone == null) {
126	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
127	        }
128	        owner.setTelephone(telephone);
129	        LocalDate effectiveDate = owner.getRegistrationDate() != null
130	            ? owner.getRegistrationDate() : LocalDate.now();
131	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
132	        if (isDailyLimitReached(owner.getRegistrationDate())) {
133	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
134	        }
135	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
136	        if (sharesHousehold) {
137	            owner.setHouseholdId(householdId(owner.getLastName(), owner.getAddress()));
138	        }
139	        if (isDuplicate(owner)) {
140	            return new ResponseEntity<>(HttpStatus.CONFLICT);
141	        }
142	        if (isCityAtCapacity(owner.getCity())) {
143	            return new ResponseEntity<>(HttpStatus.CONFLICT);
144	        }
145	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
146	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
147	        owner.setBulkSignupWarning(isBulkSignup(owner.getRegistrationDate()));
148	        owner.setHouseholdSize(householdSize(owner.getHouseholdId()));
149	        this.clinicService.saveOwner(owner);
150	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
151	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
152	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
153	        headers.setLocation(UriComponentsBuilder.newInstance()
154	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
155	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
156	    }
157	
158	    /**
159	     * Build the customer code for a newly created owner, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}
160	     * where CITY3 is the upper-cased first three letters of {@code city}, LAST3 the upper-cased first
161	     * three letters of {@code lastName} and NNNN a per-city 4-digit zero-padded sequence equal to one
162	     * more than the number of owners already in that city (e.g. {@code 'LON-SMI-0007'}).
163	     */
164	    private String nextCustomerCode(String city, String lastName) {
165	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
166	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
167	        int sequence = (int) this.clinicService.findAllOwners().stream()
168	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
169	            .count() + 1;
170	        return String.format("%s-%s-%04d", city3, last3, sequence);
171	    }
172	
173	    /**
174	     * Whether the per-day owner creation limit has been reached for the given business day, i.e.
175	     * 100 or more owners already carry that {@code registrationDate}. The day is the adjusted
176	     * (business-day) registration date of the owner being created, so owners are counted per
177	     * business day. When true, a new owner must be rejected with {@code 429 Too Many Requests}.
178	     */
179	    private boolean isDailyLimitReached(LocalDate day) {
180	        long count = this.clinicService.findAllOwners().stream()
181	            .filter(existing -> day.equals(existing.getRegistrationDate()))
182	            .count();
183	        return count >= 100;
184	    }
185	
186	    /**
187	     * Whether creating this owner pushes the day's total past the bulk-signup threshold, i.e.
188	     * more than 80 owners have already been created for the given business day. Counts the owners
189	     * already carrying that {@code registrationDate} (the same accumulation as the daily-limit
190	     * rule); when that count exceeds 80 the newly created owner is flagged with a bulk-signup
191	     * warning.
192	     */
193	    private boolean isBulkSignup(LocalDate day) {
194	        long count = this.clinicService.findAllOwners().stream()
195	            .filter(existing -> day.equals(existing.getRegistrationDate()))
196	            .count();
197	        return count > 80;
198	    }
199	
200	    /**
201	     * Roll a registration date forward onto a business day: when it falls on a Saturday or Sunday,
202	     * advance it to the following Monday; a weekday is returned unchanged.
203	     */
204	    private LocalDate toBusinessDay(LocalDate date) {
205	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
206	            date = date.plusDays(1);
207	        }
208	        return date;
209	    }
210	
211	    /**
212	     * Whether the given city has reached its owner capacity, i.e. it already contains 50 or
213	     * more owners. Cities are compared case-insensitively, matching {@link #nextCustomerCode}.
214	     */
215	    private boolean isCityAtCapacity(String city) {
216	        long count = this.clinicService.findAllOwners().stream()
217	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
218	            .count();
219	        return count >= 50;
220	    }
221	
222	    /**
223	     * The number of existing owners that already share the given firstName and lastName,
224	     * compared case-insensitively (and with surrounding whitespace trimmed and internal
225	     * whitespace runs collapsed). Counted over the owners present before this create.
226	     */
227	    private int namesakeCount(String firstName, String lastName) {
228	        String candidateFirstName = normalizeName(firstName);
229	        String candidateLastName = normalizeName(lastName);
230	        return (int) this.clinicService.findAllOwners().stream()
231	            .filter(existing -> normalizeName(existing.getFirstName()).equals(candidateFirstName)
232	                && normalizeName(existing.getLastName()).equals(candidateLastName))
233	            .count();
234	    }
235	
236	    /**
237	     * The number of members in this owner's household after this create: the count of existing
238	     * owners already carrying the same non-null {@code householdId} plus one for the owner being
239	     * created. An owner with no household ({@code householdId == null}) is a household of one.
240	     * Owners sharing a household are matched by their assigned {@code householdId}, so the count
241	     * does not depend on the order in which household members were created.
242	     */
243	    private int householdSize(String householdId) {
244	        if (householdId == null) {
245	            return 1;
246	        }
247	        long existing = this.clinicService.findAllOwners().stream()
248	            .filter(other -> householdId.equals(other.getHouseholdId()))
249	            .count();
250	        return (int) existing + 1;
251	    }
252	
253	    /**
254	     * The number of national (subscriber) digits required for each known country calling
255	     * code, keyed by the code's digits (without the leading '+'). A number whose country
256	     * code appears here must carry exactly this many digits after the code, e.g. '+61'
257	     * requires 9 national digits and '+1' requires 10.
258	     */
259	    private static final Map<String, Integer> NATIONAL_DIGITS_BY_COUNTRY = Map.of(
260	        "1", 10,
261	        "61", 9);
262	
263	    /**
264	     * Convert a raw telephone input to its E.164 representation, or {@code null} if it
265	     * cannot form a valid E.164 number.
266	     *
267	     * <p>A leading '+' and country code are kept when present; otherwise country code
268	     * '+61' is assumed and a single leading '0' is dropped from the national digits.
269	     * Spaces, dashes and brackets (indeed any non-digit) are stripped. The result must
270	     * carry 8 to 15 digits after the '+', and — for a recognised country calling code —
271	     * exactly the national-digit count that code requires (see
272	     * {@link #NATIONAL_DIGITS_BY_COUNTRY}); otherwise it is rejected as invalid.
273	     */
274	    private String toE164(String telephone) {
275	        if (telephone == null) {
276	            return null;
277	        }
278	        boolean hasCountryCode = telephone.trim().startsWith("+");
279	        String digits = telephone.replaceAll("\\D", "");
280	        String e164;
281	        if (hasCountryCode) {
282	            e164 = digits;
283	        } else {
284	            if (digits.startsWith("0")) {
285	                digits = digits.substring(1);
286	            }
287	            e164 = "61" + digits;
288	        }
289	        if (e164.length() < 8 || e164.length() > 15) {
290	            return null;
291	        }
292	        if (!hasValidNationalLength(e164)) {
293	            return null;
294	        }
295	        return "+" + e164;
296	    }
297	
298	    /**
299	     * Whether the E.164 digit string (no leading '+') carries the national-number length
300	     * required by its country calling code. The longest matching known code wins; a number
301	     * whose country code is not recognised passes this check (its length is governed only by
302	     * the general 8-15 digit bound in {@link #toE164}).
303	     */
304	    private boolean hasValidNationalLength(String e164) {
305	        return NATIONAL_DIGITS_BY_COUNTRY.entrySet().stream()
306	            .filter(entry -> e164.startsWith(entry.getKey()))
307	            .max(Comparator.comparingInt(entry -> entry.getKey().length()))
308	            .map(entry -> e164.length() - entry.getKey().length() == entry.getValue())
309	            .orElse(true);
310	    }
311	
312	    /**
313	     * Whether the candidate owner duplicates an owner that already exists, and so must be
314	     * rejected with {@code 409 Conflict}. All duplicate detection is consolidated into a single
315	     * derived {@link Owner#getIdentityKey() identityKey} — the normalized telephone, email (or
316	     * empty) and householdId (or empty) joined with {@code '|'} — and an owner is a duplicate only
317	     * when its WHOLE identity key equals that of an existing owner. Because the telephone is part
318	     * of the key, two members of the same household with different telephones have different
319	     * identity keys and are both allowed; only an exact full-key match is a duplicate.
320	     */
321	    private boolean isDuplicate(Owner owner) {
322	        String identityKey = owner.getIdentityKey();
323	        return this.clinicService.findAllOwners().stream()
324	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
325	    }
326	
327	    /**
328	     * Normalize an owner's name for household comparison: trim, collapse internal whitespace runs
329	     * to a single space and lower-case. A null value normalizes to the empty string.
330	     */
331	    private String normalizeName(String value) {
332	        if (value == null) {
333	            return "";
334	        }
335	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
336	    }
337	
338	    /**
339	     * A stable shared identifier for the household formed by a given lastName and address.
340	     * Derived deterministically from the normalized (case-insensitive, whitespace-collapsed)
341	     * lastName and address, so every owner sharing the same household is assigned the same
342	     * value regardless of the order in which they are created. Formatted as the first 12
343	     * upper-case hex characters of the SHA-256 of {@code '<lastName>|<address>'}.
344	     */
345	    private String householdId(String lastName, String address) {
346	        String key = normalizeName(lastName) + "|" + addressNormalizer.normalize(address);
347	        try {
348	            byte[] digest = MessageDigest.getInstance("SHA-256")
349	                .digest(key.getBytes(StandardCharsets.UTF_8));
350	            StringBuilder sb = new StringBuilder(digest.length * 2);
351	            for (byte b : digest) {
352	                sb.append(String.format("%02x", b));
353	            }
354	            return sb.substring(0, 12).toUpperCase();
355	        }
356	        catch (NoSuchAlgorithmException e) {
357	            throw new IllegalStateException("SHA-256 not available", e);
358	        }
359	    }
360	
361	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
362	    @Override
363	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
364	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
365	        if (currentOwner == null) {
366	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
367	        }
368	        currentOwner.setAddress(ownerFieldsDto.getAddress());
369	        currentOwner.setCity(ownerFieldsDto.getCity());
370	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
371	        currentOwner.setLastName(ownerFieldsDto.getLastName());
372	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
373	        this.clinicService.saveOwner(currentOwner);
374	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
375	    }
376	
377	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
378	    @Transactional
379	    @Override
380	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
381	        Owner owner = this.clinicService.findOwnerById(ownerId);
382	        if (owner == null) {
383	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
384	        }
385	        this.clinicService.deleteOwner(owner);
386	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
387	    }
388	
389	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
390	    @Override
391	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
392	        Owner owner = this.clinicService.findOwnerById(ownerId);
393	        if (owner == null) {
394	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
395	        }
396	        HttpHeaders headers = new HttpHeaders();
397	        Pet pet = petMapper.toPet(petFieldsDto);
398	        owner.setId(ownerId);
399	        pet.setOwner(owner);
400	        pet.getType().setName(null);
401	        this.clinicService.savePet(pet);
402	        PetDto petDto = petMapper.toPetDto(pet);
403	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
404	            .buildAndExpand(pet.getId()).toUri());
405	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
406	    }
407	
408	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
409	    @Override
410	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
411	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
412	        if (currentOwner != null) {
413	            Pet currentPet = this.clinicService.findPetById(petId);
414	            if (currentPet != null) {
415	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
416	                currentPet.setName(petFieldsDto.getName());
417	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
418	                this.clinicService.savePet(currentPet);
419	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
420	            }
421	        }
422	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
423	    }
424	
425	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
426	    @Override
427	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
428	        HttpHeaders headers = new HttpHeaders();
429	        Visit visit = visitMapper.toVisit(visitFieldsDto);
430	        Pet pet = new Pet();
431	        pet.setId(petId);
432	        visit.setPet(pet);
433	        this.clinicService.saveVisit(visit);
434	        VisitDto visitDto = visitMapper.toVisitDto(visit);
435	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
436	            .buildAndExpand(visit.getId()).toUri());
437	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
438	    }
439	
440	
441	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
442	    @Override
443	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
444	        Owner owner = this.clinicService.findOwnerById(ownerId);
445	        if (owner != null) {
446	            Pet pet = owner.getPet(petId);
447	            if (pet != null) {
448	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
449	            }
450	        }
451	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
452	    }
453	}
